mapper.select:
SELECT t.tool_id, t.tool_code, t.tool_name, t.tool_type, t.status, t.revision, COALESCE(published.exposed_name, draft.exposed_name) AS exposed_name, COALESCE(published.description, draft.description, '') AS description, published.tool_version_id AS published_version_id, published.version_no AS published_version_no, draft.tool_version_id AS draft_version_id, ( SELECT COUNT(DISTINCT a.agent_id) FROM squad_chat.sq_tool_version tv JOIN squad_chat.sq_agent_version_tool binding ON binding.tool_version_id = tv.tool_version_id JOIN squad_chat.sq_agent a ON a.current_version_id = binding.agent_version_id WHERE tv.tool_id = t.tool_id AND a.status = 'ENABLED' ) AS usage_count, t.last_update_time FROM squad_chat.sq_tool t LEFT JOIN LATERAL ( SELECT v.tool_version_id, v.version_no, v.exposed_name, v.description FROM squad_chat.sq_tool_version v WHERE v.tool_id = t.tool_id AND v.status = 'PUBLISHED' ORDER BY v.version_no DESC LIMIT 1 ) published ON TRUE LEFT JOIN squad_chat.sq_tool_version draft ON draft.tool_id = t.tool_id AND draft.status = 'DRAFT'
t.tool_id = #{toolId}
ORDER BY t.last_update_time DESC, t.id DESC
